private bool _updatingLanguages;

public int LanguageIndex
{
    get => _languageIndex;
    set
    {
        if (!Set(ref _languageIndex, value) || _updatingLanguages ||
            value < 0 || value >= possibleOcrLanguages.Count)
        {
            return;
        }

        _powerOcrSettings.Properties.PreferredLanguage =
            possibleOcrLanguages[value].LanguageTag;
        NotifySettingsChanged();
    }
}

