private static bool IsStoredLanguageMatch(string? value, Language language)
{
    return string.Equals(value, language.LanguageTag, StringComparison.OrdinalIgnoreCase) ||
           string.Equals(value, language.NativeName, StringComparison.OrdinalIgnoreCase) ||
           string.Equals(value, language.DisplayName, StringComparison.Ordinal);
}

var selectedIndex = possibleOcrLanguages.FindIndex(
    language => IsStoredLanguageMatch(savedPreference, language));

var preferred = languages.FirstOrDefault(language =>
    IsStoredLanguageMatch(userSettings.PreferredLanguage.Value, language));
selectedLanguage = preferred ?? ImageMethods.GetOCRLanguage();

var comboItem = LanguagesComboBox.Items
    .OfType<ComboBoxItem>()
    .FirstOrDefault(item => Equals(item.Tag, selectedLanguage));
